create table if not exists public.shows_app_calendar_research_controls (
  control_id text primary key,
  event_label text not null,
  event_start date not null,
  event_end date,
  profile_id text,
  disposition text not null check (disposition in ('PURSUE','WATCH','RESEARCH','SUPPRESS')),
  priority text not null check (priority in ('HIGH','MEDIUM','LOW')),
  identity_treatment text not null,
  price_text text,
  rationale text not null,
  verification_state text not null check (verification_state in ('CURRENT_WEB_VERIFIED','RECOVERED_AUDIT')),
  source_url text,
  calendar_visibility boolean not null default true,
  plan_year integer not null default 2026,
  research_batch text not null default '2026-09-13_FINAL_REMAINDER_2026_AUDIT',
  source_ref text not null default 'CHATGPT_ARCHIVE:2026-09-13_FINAL_REMAINDER_2026_AUDIT',
  active boolean not null default true,
  checked_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
alter table public.shows_app_calendar_research_controls enable row level security;

on conflict (control_id) do update set
  event_label=excluded.event_label,
  event_start=excluded.event_start,
  event_end=excluded.event_end,
  profile_id=excluded.profile_id,
  disposition=excluded.disposition,
  priority=excluded.priority,
  identity_treatment=excluded.identity_treatment,
  price_text=excluded.price_text,
  rationale=excluded.rationale,
  verification_state=excluded.verification_state,
  source_url=excluded.source_url,
  calendar_visibility=excluded.calendar_visibility,
  active=true,
  updated_at=now();
